/* Lazy book data (Phase 3). Loaded FIRST on the generated page lazy.html, which omits the <script> tags of the big,
 * self-contained data files listed in window.SB_LAZY_MANIFEST (generated by tools/build/make_lazy.js).
 *
 * Each omitted file is stood in for until it is first needed, so every other script keeps working unchanged:
 *   - a global array/object (ENGLISH_12_DATA, MATH_2_DATA, ...) is a forwarding Proxy: `typeof X`, Array.isArray(X) and
 *     `X in window` do not load anything; the first real use (X.length, X[0], for..of, JSON.stringify, ...) loads the file,
 *     replaces the stand-in by the real value, and forwards.
 *   - a book in a container (CLS2_BOOKS.math, CLASS11_BOOKS.chem) is an accessor property of the pre-created container: the first read
 *     loads the file, which then assigns the real value. Object.keys(CLS2_BOOKS) lists every book without loading.
 *   - a public function of such a file (renderChemistry11Tab...) is a stub that loads the file and calls the real function.
 * A file is fetched with a synchronous request (same origin, once per file) and run in global scope with its top-level
 * const/let/var turned into window properties. SBLazy.stats() says what has been loaded.
 * In tests (Node) set window.SB_LAZY_FETCH = url => text. Nothing here changes what the data contains. */
(function () {
  'use strict';
  const M = window.SB_LAZY_MANIFEST;
  if (!M || !M.files) return;
  const loaded = new Set(), log = [];
  const fetchSync = window.SB_LAZY_FETCH || function (url) {
    const x = new XMLHttpRequest();
    x.open('GET', url, false);
    x.send();
    if ((x.status !== 200 && x.status !== 0) || (x.status === 0 && !x.responseText)) throw new Error('SBLazy: cannot load ' + url + ' (' + x.status + ')');   // status 0 with no text = no network and nothing cached
    return x.responseText;
  };
  const byFile = {};
  M.files.forEach(f => { byFile[f.src] = f; });

  // the file is requested by content hash (file?v=<12 hex>): same bytes, same URL, cacheable for a year; changed bytes, new URL
  const url = f => f.v ? f.src + '?v=' + f.v : f.src;

  const CONST = /^(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/gm;                // top-level const/let/var become window properties (a script tag would make them global bindings)
  const run = (code, src) => (0, eval)(code.replace(CONST, 'window.$1 =') + '\n//# sourceURL=' + src);

  // preload(src): fetch a file (and the files that go with it) in the background, without blocking the page; a later loadFile() finds the text and
  // only has to run it. Used for data that is wanted soon but not now (the word table): the synchronous request of loadFile() freezes the page for as
  // long as the download takes, seconds on a slow connection. Resolves when the text is here; rejects when it cannot be fetched (the sync path then
  // behaves as before).
  const pre = new Map();
  function preload(src) {
    const f = byFile[src];
    if (!f || loaded.has(src) || !window.fetch) return Promise.resolve();
    return Promise.all([f].concat(f.also || [], f.after || []).map(o => {
      const u = url(o);
      if (pre.has(u)) return null;
      return fetch(u).then(r => { if (!r.ok) throw new Error('SBLazy: cannot preload ' + u + ' (' + r.status + ')'); return r.text(); }).then(t => { pre.set(u, t); });
    })).then(() => undefined);
  }

  function loadFile(src) {
    if (loaded.has(src)) return;
    loaded.add(src);                                  // before running: the file itself touches its own names
    const f = byFile[src];
    const t0 = Date.now();
    // Fetch everything first: a failed fetch (offline, subject not downloaded) leaves nothing half-run and the file can be asked for again
    // later. Order of execution: the file, then files that set the same DATA keys (the later definition wins in the normal page), then the
    // scripts that only patch its data, each in the original order.
    const parts = [f].concat(f.also || [], f.after || []);
    let texts;
    try { texts = parts.map(o => { const u = url(o); if (pre.has(u)) { const t = pre.get(u); pre.delete(u); return t; } return fetchSync(u); }); }   // text fetched ahead by preload(): no waiting here
    catch (e) {
      loaded.delete(src);
      try { window.dispatchEvent(new CustomEvent('sb:lazy-error', { detail: { src } })); } catch (x) { /* no events in this environment */ }
      throw e;
    }
    parts.forEach((o, i) => run(texts[i], o.src));
    log.push({ src: f.src, bytes: f.bytes, ms: Date.now() - t0, by: window.__sbCurrentSrc || null });
  }

  // ---- containers first: CLSn_BOOKS / CLSn_SOLUTIONS exist before any script uses them
  (M.containers || []).forEach(name => { if (!window[name]) window[name] = {}; });
  M.files.forEach(f => {
    Object.keys(f.keys || {}).forEach(container => {
      f.keys[container].forEach(key => {
        Object.defineProperty(window[container], key, {
          configurable: true, enumerable: true,
          get() { loadFile(f.src); const d = Object.getOwnPropertyDescriptor(window[container], key); return d && 'value' in d ? d.value : undefined; },
          set(v) { Object.defineProperty(window[container], key, { value: v, writable: true, configurable: true, enumerable: true }); },
        });
      });
    });
  });

  // ---- named globals: forwarding proxies
  function stub(name, kind, src) {
    const target = kind === 'array' ? [] : {};
    const real = () => {
      loadFile(src);
      const v = window[name];
      if (v === proxy) throw new Error('SBLazy: ' + src + ' did not define ' + name);
      return v;
    };
    const handler = {
      get: (t, k) => Reflect.get(real(), k),
      set: (t, k, v) => Reflect.set(real(), k, v),
      has: (t, k) => Reflect.has(real(), k),
      deleteProperty: (t, k) => Reflect.deleteProperty(real(), k),
      ownKeys: () => Reflect.ownKeys(real()),
      getOwnPropertyDescriptor: (t, k) => Reflect.getOwnPropertyDescriptor(real(), k),
      defineProperty: (t, k, d) => Reflect.defineProperty(real(), k, d),
      getPrototypeOf: () => Reflect.getPrototypeOf(real()),
      setPrototypeOf: (t, p) => Reflect.setPrototypeOf(real(), p),
      isExtensible: t => Reflect.isExtensible(t),            // must mirror the target (a Proxy invariant); no load
      preventExtensions: () => false,
    };
    const proxy = new Proxy(target, handler);
    return proxy;
  }
  M.files.forEach(f => {
    (f.stubs || []).forEach(s => {
      if (!(s.name in window)) window[s.name] = stub(s.name, s.kind, f.src);
    });
  });

  // ---- public functions of a lazy file (the Class 11 renderers, Class 12 Maths helpers...): a stub that loads the file, then calls
  // the real function, which the file's own declaration has put in the stub's place. The build refuses files whose functions
  // another script reassigns (that wrapper would be overwritten when the file loads).
  M.files.forEach(f => {
    (f.fns || []).forEach(name => {
      if (name in window) return;
      const forward = function () {
        loadFile(f.src);
        const real = window[name];
        if (real === forward) throw new Error('SBLazy: ' + f.src + ' did not define ' + name);
        return real.apply(this, arguments);
      };
      window[name] = forward;
    });
  });

  // ---- keys a lazy file adds to the shared registry (Object.assign(DATA, { chemChapters, chem10Chapters }) and DATA.urduChapters = URDU_DATA):
  // DATA is a const of data.js, so the generated page calls attachData(DATA) right after that script. Until the file loads each key is an
  // accessor; the file's own assignment turns it back into a plain value.
  function attachData(data) {
    M.files.forEach(f => {
      (f.dataKeys || []).forEach(key => {
        Object.defineProperty(data, key, {
          configurable: true, enumerable: true,
          get() { loadFile(f.src); const d = Object.getOwnPropertyDescriptor(data, key); return d && 'value' in d ? d.value : undefined; },
          set(v) { Object.defineProperty(data, key, { value: v, writable: true, configurable: true, enumerable: true }); },
        });
      });
    });
  }

  window.SBLazy = {
    manifest: M,
    attachData,
    isLoaded: src => loaded.has(src),
    preload,
    loadAll() { M.files.forEach(f => loadFile(f.src)); },
    stats() {
      return { files: M.files.length, loaded: log.length, bytesLoaded: log.reduce((n, l) => n + l.bytes, 0), bytesTotal: M.files.reduce((n, f) => n + f.bytes, 0), ms: log.reduce((n, l) => n + l.ms, 0), log: log.slice() };
    },
  };
})();
